contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint[] memory v) public payable {
        // General rule target:
        // - if _tos is empty, transfer must revert
        // - if _tos is non-empty:
        //     transfer reverts iff, for at least one i, caddress.call(transferFrom(from, _tos[i], v[i])) fails
        //     transfer returns true otherwise
        //
        // The test records the direct result and separately probes each element using a mirror
        // external call with the same selector/arguments. Revert flags are then compared.

        bool reverted;
        try c.transfer(from, caddress, tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool anySubcallFails = false;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));

        for (uint i = 0; i < tos.length; i++) {
            bool subOk;
            bytes memory data = abi.encodeWithSelector(id, from, tos[i], v[i]);
            (subOk, ) = caddress.call(data);
            if (!subOk) {
                anySubcallFails = true;
            }
        }

        bool shouldRevert = (tos.length == 0) || anySubcallFails;
        assert(reverted == shouldRevert);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint[] memory v) public payable {
        require(tos.length == v.length);

        // Helper contract that exposes the same selector externally so we can
        // independently probe whether the subcalls that transfer would make
        // would succeed or fail, without changing c's state.
        bool reverted;
        bool returnedTrue = false;

        try c.transfer(from, caddress, tos, v) returns (bool ok) {
            returnedTrue = ok;
            reverted = false;
        } catch {
            reverted = true;
        }

        bool probeOk;
        bytes memory callData = abi.encodeWithSelector(
            bytes4(keccak256("transferFrom(address,address,uint256)")),
            from,
            tos.length > 0 ? tos[0] : address(0),
            v.length > 0 ? v[0] : 0
        );
        (probeOk, ) = caddress.call(callData);

        // General rule: transfer returns true exactly when it does not revert,
        // and it reverts whenever the destination call target does not implement
        // the expected transferFrom selector (or the input arrays are empty).
        // For a non-empty input whose first subcall target rejects the call,
        // the whole transfer must revert; when the first subcall target accepts,
        // a successful completion must have returned true.
        assert(reverted || returnedTrue);
    }

    receive() external payable {}
}

