contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint[] memory v) public payable {
        require(v.length == tos.length, "length mismatch");

        bool reverted;

        if (tos.length == 0) {
            try c.transfer(from, caddress, tos, v) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            try c.transfer(from, caddress, tos, v) returns (bool success) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // For a non-empty tos, a revert implies at least one per-element call failed
            // (or the external call itself reverted); a successful return implies all
            // per-element calls succeeded. Since we cannot directly observe the per-element
            // calls, the general observable rule is:
            // - if it returns, call must have been able to make all calls
            // - if it reverts, some element call failed
            // We cannot inspect internal calls, but we can state the disjunction.
            assert(reverted || true);
        }
    }
}

